import type { Theme } from "@types";

import auroraTokens from "@theme/tokens/aurora";

import { createTheme } from "../utils/create-theme";

export type AuroraTheme = Theme & typeof auroraTokens;

export const getAuroraTheme = (options = { useCSSVariables: true }) => {
  let theme = createTheme<AuroraTheme>({
    /*
      This value is enabled by default and enables the use of CSS variables for theming.
      These CSS variables will cascade down to all components. If you would like not not 
      make use of CSS variables, set this value to false.

      Naming convention for CSS variables follows this pattern:
        theme.color.background.default -> --ntx-palette-background-color
    */
    useCSSVariables: options.useCSSVariables,
  });

  // Aurora tokens
  theme = createTheme<AuroraTheme>(theme, auroraTokens);

  // Create theme scoped styles that will apply to all elements within a <ThemeProvider />
  theme = createTheme(theme, {
    // Styles that an apply to all elements under a theme provider (controled by "applyThemeScopedStyles" prop and defaults to true)
    // This will override any all global CSS of matching keys within a <ThemeProvider />
    // This can accept a JSS object, CSS string, or stringified CSS file
    themeScopedStyles: {
      color: theme.color.content.default,
      ...theme.typography.body.md,
    },
  });

  // Component variants
  theme = createTheme<AuroraTheme>(theme, {
    componentVariants: {},
  });

  return theme;
};

const auroraTheme = getAuroraTheme();
export default auroraTheme;
